    async fn reconcile_checkpoint_state(&self) -> anyhow::Result<()> {
        let items = self.select_work_items().await?;
        for owner in items
            .iter()
            .filter(|item| item.parent_work_item_id.is_none() && item.external_task_id.is_some())
        {
            if let Err(error) = self
                .checkpoint_and_project(owner, None, CheckpointIntent::Verification)
                .await
            {
                tracing::warn!(work_item_id = %owner.id, error = ?error, "checkpoint reconciliation failed closed");
            }
        }
        self.retry_ownership_returns().await
    }

    async fn retry_ownership_returns(&self) -> anyhow::Result<()> {
        let path = Arc::clone(&self.db_path);
        let obligations = tokio::task::spawn_blocking(
            move || -> anyhow::Result<Vec<OwnershipReturn>> {
                let conn = Connection::open(path.as_path())?;
                let mut stmt = conn.prepare(
                    "SELECT root_work_item_id, task_id, human_owner, human_owner_provider_id, human_owners_json FROM ownership_return_outbox ORDER BY updated_at ASC",
                )?;
                let rows = stmt.query_map([], |row| {
                    let root_id: String = row.get(0)?;
                    let owners_json: String = row.get(4)?;
                    Ok((root_id, row.get(1)?, row.get(2)?, row.get(3)?, owners_json))
                })?;
                rows.map(|row| {
                    let (root_id, task_id, human_owner, human_owner_provider_id, owners_json) = row?;
                    Ok((
                        Uuid::parse_str(&root_id)?,
                        task_id,
                        human_owner,
                        human_owner_provider_id,
                        serde_json::from_str(&owners_json)?,
                    ))
                })
                .collect()
            },
        )
        .await??;
        for (root_id, task_id, human_owner, human_owner_provider_id, mut human_owners) in
            obligations
        {
            if human_owners.is_empty()
                && (human_owner_provider_id.is_some() || human_owner.is_some())
            {
                human_owners.push(ProviderIdentity {
                    provider_id: human_owner_provider_id.clone(),
                    display_name: human_owner.clone(),
                });
            }
            validate_exact_remembered_human_owners(&root_id.to_string(), &human_owners)?;
            let ownership = ProviderOwnership::Human {
                owners: human_owners.clone(),
            };
            let adapter = Arc::clone(&self.task_adapter);
            let task_id_for_call = task_id.clone();
            let result = tokio::task::spawn_blocking(move || {
                adapter.set_ownership(&task_id_for_call, &ownership)
            })
            .await
            .map_err(|error| anyhow::anyhow!("ownership retry task failed: {error}"))?;
            match result {
                Ok(()) => self.clear_ownership_return(root_id).await?,
                Err(error) => {
                    self.enqueue_ownership_return(
                        root_id,
                        &task_id,
                        human_owner.as_deref(),
                        human_owner_provider_id.as_deref(),
                        &human_owners,
                        Some(&format!("{error:#}")),
                    )
                    .await?;
                }
            }
        }
        Ok(())
    }

    async fn cancel_work_item_due_to_deleted_external_task(
        &self,
        item: &WorkItem,
        task_id: &str,
    ) -> anyhow::Result<()> {
        if item.state == WorkItemState::Cancelled {
            return Ok(());
        }

        let (mut updated, _) = self
            .cancel_work_item_tree_durable(item.id)
            .await
            .map_err(|error| anyhow::anyhow!(error.to_string()))?;
        updated.human_gate = false;
        updated.human_gate_state = None;
        updated.write_back_failures = 0;
        updated.write_back_retry_after = None;
        updated.updated_at = Utc::now();
        updated.blocked_on = block_reason_for_state_name(&updated.current_step);
        updated.projected_state = Some(project_workflow_state(&updated));

        tracing::warn!(
            "External task {task_id} was deleted, cancelling work item {}",
            updated.id
        );

        self.update_work_item(&updated).await?;
        Ok(())
    }

    async fn persist_ownership_transition_locked(
        &self,
        item: &mut WorkItem,
        ownership: &ProviderOwnership,
        cancel_unreleased: bool,
    ) -> anyhow::Result<()> {
        let path = Arc::clone(&self.db_path);
        let item_id = item.id;
        let ownership_json = serde_json::to_string(ownership)?;
        let remembered_human_owners_json = serde_json::to_string(&item.remembered_human_owners)?;
        let updated_at = Utc::now();
        tokio::task::spawn_blocking(move || -> anyhow::Result<()> {
            let mut conn = Connection::open(path.as_path())?;
            let tx = begin_immediate_transaction(&mut conn)?;
            tx.execute(
                "UPDATE work_items SET provider_ownership_json = ?2, remembered_human_owners_json = ?3, updated_at = ?4 WHERE id = ?1",
                params![
                    item_id.to_string(),
                    ownership_json,
                    remembered_human_owners_json,
                    updated_at.to_rfc3339(),
                ],
            )?;
            if cancel_unreleased {
                tx.execute(
                    "UPDATE jobs SET state = ?2, updated_at = ?3 WHERE checkpoint_owner_id = ?1 AND dispatch_released = 0 AND state = ?4",
                    params![
                        item_id.to_string(),
                        JobState::Cancelled.to_string(),
                        updated_at.to_rfc3339(),
                        JobState::Pending.to_string(),
                    ],
                )?;
            }
            tx.commit()?;
            Ok(())
        })
        .await??;
        item.provider_ownership = ownership.clone();
        item.updated_at = updated_at;
        Ok(())
    }

    async fn write_back_projection(&self, item: &WorkItem) -> anyhow::Result<ProjectionResult> {
        if self.should_skip_write_back(item) {
            return Ok(ProjectionResult::SkippedDueToBackoff);
        }

        let Some(task_id) = item.external_task_id.clone() else {
            return Ok(ProjectionResult::Completed);
        };
        let now = Utc::now();

        let labels = TaskLabels {
            workflow: Some(item.workflow_id.clone()),
            step: Some(item.current_step.clone()),
            phase: Some(derive_phase(item)),
            failed: item.state == WorkItemState::Failed || item.last_failure_reason.is_some(),
        };

        let ownership = if item.human_gate {
            remembered_human_ownership(item, self.operator_login.as_deref())
        } else if item.provider_ownership.is_bot_only() {
            ProviderOwnership::Bot
        } else {
            item.provider_ownership.clone()
        };
        let projected_ownership = ownership.clone();

        let mut wrote_back = false;
        let mut first_error: Option<anyhow::Error> = None;
        let adapter = Arc::clone(&self.task_adapter);
        let projection_task_id = task_id.clone();
        let (labels_result, assignee_result) = tokio::task::spawn_blocking(move || {
            let labels_result = adapter.set_labels(&projection_task_id, &labels);
            let assignee_result = adapter.set_ownership(&projection_task_id, &ownership);
            (labels_result, assignee_result)
        })
        .await
        .map_err(|error| anyhow::anyhow!("provider projection task failed: {error}"))?;

        if let Err(error) = labels_result {
            if external_task_not_found_id(&error).is_some() {
                return Err(error);
            }
            eprintln!("write-back labels failed for {task_id}: {error:#}");
            if first_error.is_none() {
                first_error = Some(anyhow::anyhow!(error.to_string()));
            }
        } else {
            wrote_back = true;
        }
        if let Err(error) = assignee_result {
            if external_task_not_found_id(&error).is_some() {
                return Err(error);
            }
            eprintln!("write-back assignee failed for {task_id}: {error:#}");
            if first_error.is_none() {
                first_error = Some(anyhow::anyhow!(error.to_string()));
            }
        } else {
            wrote_back = true;
            self.set_work_item_provider_ownership(item.id, &projected_ownership)
                .await?;
        }

        if let Some(error) = first_error {
            if wrote_back {
                self.set_work_item_last_written_at_only(item.id, now)
                    .await?;
            }
            self.record_write_back_failure(item, now, &error).await?;
            return Err(error);
        }

        if wrote_back {
            self.record_write_back_success(item.id, now).await?;
        }
        Ok(ProjectionResult::Completed)
    }

