fn triage_workflow_id_from_output(output: &serde_json::Value) -> Option<String> {
    output
        .get("workflow_id")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .or_else(|| {
            output
                .get("workflow")
                .and_then(serde_json::Value::as_object)
                .and_then(|workflow| workflow.get("id"))
                .and_then(serde_json::Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToOwned::to_owned)
        })
}

fn discovered_repo_catalog_entries(repos: &[DiscoveredRepo]) -> Vec<serde_json::Value> {
    repos
        .iter()
        .map(|repo| {
            let description = if let Some(remote) = repo.remote_url.as_deref() {
                format!("{} (remote: {remote})", repo.name)
            } else {
                format!("{} (remote: none)", repo.name)
            };
            serde_json::json!({
                "repo_url": repo.local_path,
                "base_ref": "origin/main",
                "description": description,
            })
        })
        .collect()
}

fn add_triage_repository_mounts(
    runtime: &mut CanonicalRuntimeSpec,
    repos: &[DiscoveredRepo],
) -> Result<(), String> {
    if let Some(repo) = repos.iter().find(|repo| {
        repo.name.is_empty()
            || repo.name == "."
            || repo.name == ".."
            || !repo.name.chars().all(|character| {
                character.is_ascii_alphanumeric() || matches!(character, '-' | '_' | '.')
            })
    }) {
        return Err(format!(
            "repository '{}' has an unsafe triage mount name",
            repo.name
        ));
    }
    runtime
        .environment
        .file_mounts
        .extend(
            repos
                .iter()
                .map(|repo| protocol::orchestration::PlannedFileMount {
                    host_path: repo.local_path.clone(),
                    container_path: format!("/repos/{}", repo.name),
                    read_only: true,
                }),
        );
    Ok(())
}

fn build_authorization_obligation(
    root: &WorkItem,
    logical_item: &WorkItem,
    job: &Job,
    request: &ResolvedAuthorizationRequest,
) -> anyhow::Result<(
    AuthorizationObligationInsert,
    CheckpointAuthorizationPending,
)> {
    if request.root_work_item_id != root.id || request.work_unit_id != logical_item.id {
        anyhow::bail!("authorization obligation work-unit binding mismatch");
    }
    let artifact = job.canonical_authorization.as_ref().ok_or_else(|| {
        anyhow::anyhow!("authorization obligation job lacks canonical authorization bytes")
    })?;
    let authorization_id = job
        .context
        .get(protocol::CONTEXT_AUTHORIZATION_ID_KEY)
        .and_then(serde_json::Value::as_str)
        .ok_or_else(|| anyhow::anyhow!("authorization obligation job lacks authorization ID"))?;
    let bundle = protocol::ImmutableAuthorizationBundle::verify(artifact, authorization_id)
        .map_err(anyhow::Error::msg)?;
    if bundle.request.clone().normalize() != request.clone().normalize() {
        anyhow::bail!("authorization obligation semantic request mismatch");
    }
    let digest = bundle.digest.clone();
    let request = bundle.request;
    let request_json = serde_json::to_string(&request)?;
    let mut authoritative_job = job.clone();
    authoritative_job.id = Uuid::new_v5(
        &root.id,
        format!("authorization-job:{}:{digest}", logical_item.id).as_bytes(),
    );
    authoritative_job.created_at = DateTime::<Utc>::UNIX_EPOCH;
    authoritative_job.updated_at = DateTime::<Utc>::UNIX_EPOCH;
    let pending = CheckpointAuthorizationPending {
        work_item_id: logical_item.id,
        request_digest: digest.clone(),
        request: serde_json::to_value(request)?,
    };
    Ok((
        AuthorizationObligationInsert {
            checkpoint_owner_id: root.id,
            work_item_id: logical_item.id,
            request_digest: digest,
            request_json,
            job_json: serde_json::to_string(&authoritative_job)?,
            canonical_authorization_version: bundle.version,
            canonical_authorization_bytes: bundle.canonical_bytes,
        },
        pending,
    ))
}

fn mark_authorization_pending(
    root: &mut WorkItem,
    pending: CheckpointAuthorizationPending,
) -> anyhow::Result<()> {
    if !root.context.is_object() {
        root.context = serde_json::json!({});
    }
    root.context["authorization_pending"] = serde_json::to_value(pending)?;
    root.human_gate = true;
    root.human_gate_state = Some("authorization_pending".to_string());
    root.required_action_description = Some(
        "Review the immutable authorization request and reassign this task to Agent Hub to authorize this job."
            .to_string(),
    );
    root.projected_state = Some("authorization_pending".to_string());
    root.updated_at = Utc::now();
    Ok(())
}

fn discovered_repo_catalog_hint(repos: &[DiscoveredRepo]) -> String {
    repos
        .iter()
        .map(|repo| {
            if let Some(remote) = repo.remote_url.as_deref() {
                format!("- {} — {} (remote: {remote})", repo.name, repo.local_path)
            } else {
                format!("- {} — {} (remote: none)", repo.name, repo.local_path)
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn is_valid_repo_source(repo: &protocol::RepoSource) -> bool {
    let repo_url = repo.repo_url.trim();
    let base_ref = repo.base_ref.trim();
    !repo_url.is_empty() && !is_placeholder_repo_url(repo_url) && !base_ref.is_empty()
}

fn is_placeholder_repo_url(repo_url: &str) -> bool {
    let normalized = repo_url.trim().to_ascii_lowercase();
    matches!(
        normalized.as_str(),
        "unknown"
            | "n/a"
            | "none"
            | "null"
            | "placeholder"
            | "repo"
            | "repo_url"
            | "todo"
            | "tbd"
            | "https://github.com/org/repo"
            | "https://example/repo"
            | "https://example/repo.git"
    )
}

fn external_task_not_found_id(error: &anyhow::Error) -> Option<String> {
    for cause in error.chain() {
        if let Some(typed) = cause.downcast_ref::<TaskAdapterError>() {
            return match typed {
                TaskAdapterError::TaskNotFound { task_id } => Some(task_id.clone()),
            };
        }
    }
    None
}

