    #[tokio::test]
    async fn stale_worker_requeues_assigned_job() {
        let harness = AuthorizedWorkflowHarness::new(workflow_catalog(), "wf", false).await;
        let svc = &harness.svc;

        svc.register_worker(RegisterWorkerRequest {
            id: "stale".into(),
            hostname: "host".into(),
            supported_modes: vec![protocol::ExecutionMode::Docker],
            protocol_capabilities: vec![
                protocol::WorkerProtocolCapability::CanonicalAuthorizationV1,
                protocol::WorkerProtocolCapability::CanonicalAuthorizationV2,
                protocol::WorkerProtocolCapability::CanonicalAuthorizationV3,
                protocol::WorkerProtocolCapability::CanonicalAuthorizationV4,
            ],
        })
        .await
        .expect("reg");

        let job = svc
            .poll_job(PollJobRequest {
                worker_id: "stale".into(),
            })
            .await
            .expect("poll")
            .job
            .expect("assigned");

        let mut stale_worker = svc
            .get_worker("stale")
            .await
            .expect("get worker")
            .expect("exists");
        stale_worker.last_heartbeat_at = Utc::now() - chrono::TimeDelta::seconds(500);
        svc.upsert_worker(&stale_worker).await.expect("backdate");

        let requeued = svc
            .reconcile_stale_workers(Duration::from_secs(30))
            .await
            .expect("reconcile");
        assert!(requeued >= 1);

        let refreshed = svc
            .get_job(job.id)
            .await
            .expect("get job")
            .expect("job exists");
        assert_eq!(refreshed.state, JobState::Pending);
        assert!(refreshed.assigned_worker_id.is_none());
    }

    #[tokio::test]
    async fn reactive_human_gate_requires_bot_assignment_before_progression() {
        let harness =
            AuthorizedWorkflowHarness::new(reactive_workflow_catalog(), "reactive_wf", true).await;
        let svc = &harness.svc;
        let adapter = Arc::clone(&harness.adapter);
        let item = harness.work_item().await;
        let first_job = harness.poll_job().await;
        assert_eq!(first_job.step_id, "run_agent");

        svc.update_job(
            first_job.id,
            JobUpdateRequest {
                worker_id: "w1".into(),
                state: JobState::Running,
                transcript_dir: None,
                result: None,
            },
        )
        .await
        .expect("running first");

        svc.update_job(
            first_job.id,
            JobUpdateRequest {
                worker_id: "w1".into(),
                state: JobState::Succeeded,
                transcript_dir: None,
                result: None,
            },
        )
        .await
        .expect("complete first");

        let review = svc
            .get_work_item(item.id)
            .await
            .expect("get")
            .expect("exists");
        assert_eq!(review.current_step, "review");
        assert_eq!(review.state, WorkItemState::Running);

        let error = svc
            .fire_event(
                item.id,
                FireEventRequest {
                    event: WorkflowEventKind::HumanChangesRequested,
                    job_id: None,
                    reason: Some("changes requested".into()),
                },
            )
            .await
            .expect_err("human-owned provider task must reject direct progression");
        assert!(
            error
                .to_string()
                .contains("provider task is not assigned exclusively to the bot")
        );
        let unchanged = svc
            .get_work_item(item.id)
            .await
            .expect("get unchanged")
            .expect("item");
        assert_eq!(unchanged.current_step, "review");

        adapter
            .set_ownership(&item.id.to_string(), &ProviderOwnership::Bot)
            .expect("assign task back to bot");
        svc.sync_tasks_from_adapter()
            .await
            .expect("assignment applies legal approval");

        let done = svc
            .get_work_item(item.id)
            .await
            .expect("get done")
            .expect("exists");
        assert_eq!(done.current_step, "done");
        assert_eq!(done.state, WorkItemState::Succeeded);
    }

