    #[tokio::test]
    async fn running_to_running_renews_lease() {
        let harness = AuthorizedWorkflowHarness::new(workflow_catalog(), "wf", true).await;
        let svc = &harness.svc;
        let job = harness.poll_job().await;

        let running = svc
            .update_job(
                job.id,
                JobUpdateRequest {
                    worker_id: "w1".into(),
                    state: JobState::Running,
                    transcript_dir: None,
                    result: None,
                },
            )
            .await
            .expect("set running");
        let first_lease = running.lease_expires_at.expect("lease set");

        tokio::time::sleep(Duration::from_millis(10)).await;

        let renewed = svc
            .update_job(
                job.id,
                JobUpdateRequest {
                    worker_id: "w1".into(),
                    state: JobState::Running,
                    transcript_dir: None,
                    result: None,
                },
            )
            .await
            .expect("renew");
        let second_lease = renewed.lease_expires_at.expect("lease set");
        assert!(second_lease > first_lease);
    }

