    #[tokio::test]
    async fn operator_retry_requeues_last_failed_reactive_step_without_retry_transition() {
        let harness = AuthorizedWorkflowHarness::new(
            reactive_failed_terminal_catalog(),
            "reactive_failed_terminal",
            true,
        )
        .await;
        let svc = &harness.svc;
        let item = harness.work_item().await;
        let failed = harness
            .complete_next_job(JobState::Failed, failed_job_result())
            .await;
        assert_eq!(failed.state, WorkItemState::Failed);
        assert_eq!(failed.current_step, "failed");
        Connection::open(&harness.db)
            .unwrap()
            .execute(
                "UPDATE jobs SET context_json = json_set(context_json,
                    '$.valid_next_events', json('[\"cancel\"]'),
                    '$.workflow.valid_next_events', json('[\"human_approved\"]'),
                    '$.workflow.inputs.valid_next_events', json('[\"timeout\"]'))
                 WHERE work_item_id = ?1 AND step_id = 'run' AND state = 'failed'",
                [item.id.to_string()],
            )
            .unwrap();

        let pending_retry = svc
            .apply_operator_action(
                item.id,
                TaskHumanAction {
                    kind: HumanActionKind::Retry,
                    workflow_id: None,
                    reason: Some("operator retry".into()),
                },
            )
            .await
            .expect("operator retry");
        assert_eq!(
            pending_retry.human_gate_state.as_deref(),
            Some("authorization_pending")
        );
        let mut bot_owned = harness.work_item().await;
        svc.persist_ownership_transition_locked(&mut bot_owned, &ProviderOwnership::Bot, false)
            .await
            .expect("persist bot ownership for operator approval");
        svc.process_provider_action(
            item.id,
            TaskHumanAction {
                kind: HumanActionKind::Approve,
                workflow_id: None,
                reason: Some("approve pending retry".to_string()),
            },
            u64::MAX - 1,
        )
        .await
        .expect("approve pending retry");
        let retried = harness.work_item().await;

        assert_eq!(retried.state, WorkItemState::Running, "{retried:?}");
        assert_eq!(retried.current_step, "run");
        assert_eq!(retried.context["operator_override"]["action"], "retry");

        let jobs = svc.list_jobs_for_work_item(item.id).await.expect("jobs");
        let retry = jobs
            .iter()
            .find(|j| j.step_id == "run" && j.state == JobState::Pending && j.attempt == 1)
            .expect("pending operator retry");
        assert_eq!(
            retry.canonical_authorization.as_ref().unwrap().version,
            protocol::CANONICAL_AUTHORIZATION_VERSION
        );
        assert!(retry.context.get("valid_next_events").is_none());
        assert!(retry.context["workflow"].get("valid_next_events").is_none());
        assert!(
            retry.context["workflow"]["inputs"]
                .get("valid_next_events")
                .is_none()
        );
    }

